    public function __construct(private ?Chat_automations_model $models=null,private ?Chat_instances_model $instances=null,private ?Chat_settings_model $settings=null,private ?N8n_client $n8n=null,private ?Audit_service $audit=null){$this->models??=new Chat_automations_model();$this->instances??=new Chat_instances_model();$this->settings??=new Chat_settings_model();$this->n8n??=new N8n_client($this->settings);$this->audit??=new Audit_service();}
